  CollectionHall_126473_Desc = {
    Text = "The cosmos birthed worlds; worlds birthed life; life birthed divergent laws and beliefs.\nWhen these lives collide, it is never a simple trial of strength or will.\nIt is the collision of two universes—eternally parallel, yet forced to intersect."
