  CollectionHall_126474_Desc = {
    Text = "When the mission ends, I will part with my old self.\nGoodbye to the past I can never go back to. To Temurahn, to the human I once was.\nI will mist that mist-shrouded place.\nI'll start over here, where the mist is gone—in this strange, terrifying new home."
