    Text = "Clear Multiverse Link \"Forgotten Seed of Love\": Hard"
  },
  CollectionHall_142160_Title = {
    Text = "Rainy Season"
  },
  CollectionHall_142161_Desc = {
    Text = [[
All life is born into ignorance, drawing sustenance from the world, reshaping its surroundings, plundering its resources to nourish the self.
Such is the original sin from which none can escape.]]
  },
  CollectionHall_142161_LockTip = {
    Text = "Clear Multiverse Link \"Forgotten Seed of Love\""
