  CollectionHall_142163_Title = {
    Text = "Roaming the Dunes"
  },
  CollectionHall_142164_Desc = {
    Text = "<Italic:\"May I call your name? Though the world all fades...\">\nIf all memories are doomed to dissolve into nothing, and pitch-black oblivion devours every unmourned moment of the past—\nthen take my hand, and let a silver radiance bind us together.\nIn a newborn dream, in the early spring when tender seeds first sprout."
  },
  CollectionHall_142164_LockTip = {
    Text = "Clear Multiverse Link \"Forgotten Seed of Love\""
  },
  CollectionHall_142164_Title = {
    Text = "Song of Memento"
  },
  CollectionHall_142165_Desc = {
    Text = "Sing aloud! For radiant life now extols its freedom, scattering the feathered seeds of hope to every corner of the earth."
  },
  CollectionHall_142165_LockTip = {
    Text = "Clear Multiverse Link \"Forgotten Seed of Love\": Hard"
  },
  CollectionHall_142165_Title = {
    Text = "Hymn of the Unveiling"
  },
  CollectionHall_142868_Desc = {
    Text = "Pontos never forgot how he felt the day he learned of his family's history. Before that, responsibility was the furthest thing from his mind. Everyone loved him—he was handsome, charming, and utterly carefree.\nThe endless stream of ships calling at @1 Port washed away the tedium of ordinary life; he had heard so many tales and was so frequently called knowledgeable that he refused to believe he would ever fade into obscurity.\nSo when the truth of his lineage was finally revealed to him, he was overwhelmed by an enormous, unexpected yet perfectly natural euphoria. Moreover, the supreme, unfathomable entity behind the Night-Gaunt his family had commanded for generations had acknowledged him. He was born for greatness.\nThen, a mere whim of \"N\" set the cultists loose, their indiscriminate coastal raid reducing his entire village to ashes.\nBroken by the sudden devastation, Pontos sacrificed his body—and all his future possibilities—to @3 in exchange for the power of the abyss.\nBut it no longer mattered. Nothing would ever slip from his grasp again.\nNothing could ever be taken from him again."
  },
  CollectionHall_142868_LockTip = {
    Text = "Unlocked after Awakening \"Pontos\""
  },
  CollectionHall_142868_Title = {Text = "Pontos"},
  CollectionHall_142901_Title = {
    Text = "Ebwynnos Evermore"
  },
  CollectionHall_143468_Desc = {
    Text = "The death knell has tolled; the betrayers offer up their maddest performance yet.\nWhat ending shall these countless threads weave together—\nthat, you shall decide."
