  },
  CollectionHall_143479_Title = {
    Text = "What Was, What Shall Be"
  },
  CollectionHall_143480_Desc = {
    Text = "A dash of bitters, 20ml of sweet vermouth, a measure of sherry, brimming with ice and stirred—a fine aperitif indeed, and a play performed five hundred times over.\nMy dear, let us, in our wine-warmed mirth, share one more dance."
