  CollectionHall_143486_Title = {
    Text = "Threads of the Living"
  },
  CollectionHall_143487_Desc = {
    Text = "When the dream ends, all shall vanish, utterly forgotten—the manor, the flower garden, the songs, the paintings...\nIt was a spring that never was."
