  CollectionHall_144454_Desc = {
    Text = "Foolish, shallow, vainglorious, solitary—the brittle despot has forged a kingdom of his own.\nImmutable shells breathe no truth; for nothing can piece together, from the ravine, a heart too afraid of change—and so shattered before its time."
