  },
  CollectionHall_89970_Desc = {
    Text = "She was born into a fate of hatred, bloodshed, and endless conflict. When she abandoned all tender illusions and chose to take up the knife and gun, fate's triumphal song had already begun to play for her. She was destined to become a warrior, washing away her hatred with her enemies' blood, then living a life that may not be glorious, but is fearless and without regret."
