  CollectionHall_89977_Desc = {
    Text = "The desert sun is unlike any other—pale, glaring, and fierce, it never shows a gentle side. A beast that knows only its scorching light cannot imagine the warm spring you describe. Go then, go, and find that gentle sun for him."
