  CollectionHall_95448_Desc = {
    Text = "The tide roars. The skulls scream.\nA thousand eyes fix upon you. A thousand mouths curse your name.\nThey will drown you. They will devour you.\nYou squeeze your eyes shut in terror—and when you open them, they surround you."
  },
  CollectionHall_95448_LockTip = {
    Text = "Complete Special Ops: \"Phantom of the Rainy Town\""
  },
  CollectionHall_95448_Title = {
    Text = "Sea of Skulls"
  },
  CollectionHall_95449_Desc = {
    Text = "She promised to take you home. Together.\n—In eternal form, to that quiet homeland of miracles and beauty."
  },
  CollectionHall_95449_LockTip = {
    Text = "Clear Psyche Deepdive: \"Melodic Sculpting\""
  },
  CollectionHall_95449_Title = {
    Text = "Art of Corallization"
  },
  CollectionHall_95450_Desc = {
    Text = "That Esteemed Guest once gazed at Castor's hopeful back beneath the moonlight, softly whispering a prophecy: \"He will walk out, and he will struggle desperately in the storm. Yet what lifts him to fly will also bring him crashing down.\""
  },
  CollectionHall_95450_LockTip = {
    Text = "Complete Dreamscape: \"Beyond the Skies: Part I\""
  },
  CollectionHall_95450_Title = {
    Text = "Eye of the Tempest"
  },
  CollectionHall_95451_Desc = {
    Text = [[
Born of beauty. Perfected in death.
She is genius, madwoman, devil. The executioner whose hands cradle your face like family.
Her scorching love preserves you: a flawless masterpiece in flesh.
She embraces you, lifts your marble-cold fingers. Together you'll return home, where art reigns eternal.]]
  },
  CollectionHall_95451_LockTip = {
    Text = "Clear Psyche Deepdive: \"Melodic Sculpting: Hard\""
  },
  CollectionHall_95451_Title = {
    Text = "Death by Beauty"
  },
  CollectionHall_95452_Desc = {
    Text = [[
The ocean heard my call, thus bringing you to my side.
From then on, we have talked, played, and rejoiced freely, destined to become the best friends in the world.
In this city full of dissolution and deathly silence.]]
  },
  CollectionHall_95452_LockTip = {
    Text = "Complete Psyche Deepdive: \"Eadem Omnia\""
  },
  CollectionHall_95452_Title = {
    Text = "Let's All Be Friends!"
  },
  CollectionHall_95453_Desc = {
    Text = "Come home, brave one. Come home, coward. Clever girl, foolish child, warrior and waif—every one of me, come home, come home.\nLet every splintered heart dissolve: the joyous, the grieving, the furious, the aching, the so very tired.\nWe are together.\nAlways and forever, they stay together."
  },
  CollectionHall_95453_LockTip = {
    Text = "Complete Special Ops: \"Serene Fission\" (Hard)"
  },
  CollectionHall_95453_Title = {
    Text = "Every One of Her"
  },
  CollectionHall_95454_Desc = {
    Text = "The void within her shattered soul can only be filled by the most innocent of fables. One day, she will bid farewell to pain and return to the joyful homeland of her fairy tales."
  },
  CollectionHall_95454_LockTip = {
    Text = "Complete Psyche Deepdive: \"Eadem Omnia\""
  },
  CollectionHall_95454_Title = {
    Text = "Innocent Horror Fairytale"
  },
  CollectionHall_95455_Desc = {
    Text = "The alleyways coiled like serpents in the gloom, narrow and suffocating, their cobbled stones steeped in the echoes of fate's cruel whims. Reunions, quarrels, partings—even violence, cruelty, and murder.\nFortunately, today's tale did not descend into the latter bloodshed. But who could say that the former did not lead to a tragedy far more profound?"
  },
